<script lang="ts" setup>
import type { MallEnterpriseApi } from '#/api/mall/product/enterprise'; import { computed, ref } from 'vue'; import { useVbenModal } from '@vben/common-ui'; import { message } from 'ant-design-vue'; import { useVbenForm } from '#/adapter/form'; import { createEnterprise, getEnterprise, updateEnterprise } from '#/api/mall/product/enterprise'; import { $t } from '#/locales'; import { useFormSchema } from '../data';
const emit=defineEmits(['success']); const formData=ref<MallEnterpriseApi.Enterprise>(); const title=computed(()=>formData.value?.id?$t('ui.actionTitle.edit',['企业档案']):$t('ui.actionTitle.create',['企业档案'])); const [Form,formApi]=useVbenForm({commonConfig:{componentProps:{class:'w-full'},formItemClass:'col-span-2',labelWidth:120},layout:'horizontal',schema:useFormSchema(),showDefaultActions:false}); const [Modal,modalApi]=useVbenModal({async onConfirm(){const {valid}=await formApi.validate();if(!valid)return;modalApi.lock();try{const d=await formApi.getValues() as MallEnterpriseApi.Enterprise;await(formData.value?.id?updateEnterprise(d):createEnterprise(d));await modalApi.close();emit('success');message.success($t('ui.actionMessage.operationSuccess'));}finally{modalApi.unlock();}},async onOpenChange(open){if(!open){formData.value=undefined;await formApi.resetForm();return;}const d=modalApi.getData<MallEnterpriseApi.Enterprise>();if(d?.id){modalApi.lock();try{formData.value=await getEnterprise(d.id);await formApi.setValues(formData.value);}finally{modalApi.unlock();}}else await formApi.resetForm();}});
</script>
<template><Modal :title="title" class="w-[560px]"><Form class="mx-4"/></Modal></template>
